        if !self.path_exists_at(rev, path)? {
            return Ok(None);
        }
        let spec = format!("{rev}:./{}", path.display());
        let args = ["show", &spec];
        let shas: Option<Vec<CommitSha>> = output.stdout_lines().map(|l| CommitSha::parse(l).ok()).collect();
        Ok(shas.filter(|shas| shas.len() == refs.len()))
    }

