        ])
    }

    /// Tracked paths, relative to the root and limited to it.
    pub fn tracked_paths(&self) -> Result<Vec<PathBuf>, VcsError> {
        self.name_only(&["ls-files", "-z"])
    }

    /// The object id each `<revision>:<path>` names, `None` for one that names nothing, from one `git cat-file
    /// --batch-check`. An empty path names the revision's root tree. Two specs name the same content exactly when their
    /// ids are equal, so this compares directories at two commits without reading either.
    pub fn object_ids(&self, specs: &[String]) -> Result<Vec<Option<String>>, VcsError> {
        if specs.is_empty() {
            return Ok(Vec::new());
        }
        let args = ["cat-file", "--batch-check"];
            .map(|pattern| match pattern.strip_suffix('/') {
                Some(directory) => format!(":(exclude,glob)**/{directory}/**"),
                None => format!(":(exclude,glob)**/{pattern}"),
            })
            .collect();
        pkgs.iter()
            .map(|pkg| {
                let tag = format!("{}@1.0.0", pkg.id);
                let tagged = run_git_ok(root, &["rev-parse", "-q", "--verify", &format!("{tag}^{{commit}}")]);
                let mut args: Vec<String> = match &tagged {
                    Some(commit) => [
                        "diff",
                        "--no-renames",
                        "--relative",
                        "--name-only",
                        "-z",
                        commit.trim(),
                        "--",
                    ]
                    .map(String::from)
                    .to_vec(),
                    None => ["ls-files", "-z", "--"].map(String::from).to_vec(),
                };
                args.extend(package_paths(pkg).iter().map(|d| d.to_string_lossy().into_owned()));
                args.extend(excludes.iter().cloned());
                let refs: Vec<&str> = args.iter().map(String::as_str).collect();
                let output = GitRunner.run("git", &refs, root).unwrap();
                let files: BTreeSet<PathBuf> = output
                    .stdout
                    .split('\0')
                    .filter(|path| !path.is_empty())
                    .map(PathBuf::from)
                    .collect();
